import re
from datetime import date
from decimal import Decimal
from typing import Annotated, Literal, Self

from pydantic import Field, JsonValue

from exposed.adapters.parliament_models import SourceDate
from exposed.core.declarations import (
    Declaration as DomainDeclaration,
)
from exposed.core.declarations import (
    DeclarationDraft,
    FunderName,
    PublishedVersion,
    latest_version,
    preferred_funder,
)
from exposed.core.declarations import (
    FundingEntry as DomainFundingEntry,
)
from exposed.core.declarations import canonical_json as canonical_json
from exposed.core.errors import DeclarationParseError as DeclarationParseError
from exposed.core.errors import ParentRequired as ParentRequired
from exposed.core.models import DisplayName, Model, PositiveID


class DeclarationPage(Model):
    # Validate each item later so malformed declarations do not discard valid siblings.
    items: list[JsonValue]
    total_results: Annotated[int, Field(ge=0)] = Field(validation_alias="totalResults")
    skip: Annotated[int, Field(ge=0)]


class Category(Model):
    id: PositiveID
    name: DisplayName
    type: Literal["Commons"]


class MemberIdentity(Model):
    id: PositiveID


class Registrant(Model):
    type: Literal["Member"]
    member: MemberIdentity = Field(validation_alias="memberDetail")


class Register(Model):
    published_date: SourceDate = Field(validation_alias="publishedDate")


class VersionHeader(Model):
    source_register: Register = Field(validation_alias="register")


class RegistrationDate(Model):
    registration_date: SourceDate | None = Field(default=None, validation_alias="registrationDate")


class SourceField(Model):
    name: str
    type: str | None = None
    type_info: dict[str, JsonValue] | None = Field(default=None, validation_alias="typeInfo")
    value: JsonValue = None
    values: list[list[SourceField]] | None = None

    def check_funding_shape(self, path: str, *, allowed: bool = True, nested: bool = False) -> None:
        has_currency = "currencyCode" in (self.type_info or {})
        financial = self.name in {"Value", "PaymentType", "Donors"} or has_currency
        if financial and (
            not allowed
            or (has_currency and self.name != "Value")
            or (nested and self.name == "Donors")
        ):
            raise DeclarationParseError(
                path, self.model_dump(by_alias=True), "unsupported funding field or nesting"
            )
        for i, group in enumerate(self.values or []):
            if self.name == "Donors" and not group:
                raise DeclarationParseError(f"{path}.values.{i}", [], "empty donor group")
            for j, field in enumerate(group):
                field.check_funding_shape(
                    f"{path}.values.{i}.{j}.{field.name}",
                    allowed=allowed and self.name == "Donors",
                    nested=True,
                )

    def text(self, path: str) -> str | None:
        if self.value is None:
            return None
        if not isinstance(self.value, str):
            raise DeclarationParseError(path, self.value, "expected a string")
        return self.value if self.value.strip() else None


class FundingEntry(DomainFundingEntry):
    """Decode Parliament fields, retaining the core funding value's validation."""

    @classmethod
    def from_fields(cls, fields: list[SourceField], path: str, *, donor: bool = False) -> Self:
        indexed = {f.name: (i, f) for i, f in enumerate(fields)}
        if len(indexed) != len(fields):
            raise DeclarationParseError(path, [f.name for f in fields], "repeated field names")

        def text(name: str) -> str | None:
            if name not in indexed:
                return None
            i, f = indexed[name]
            return f.text(f"{path}.{i}.{name}.value")

        def funder_name(name: str) -> FunderName:
            try:
                value = text(name)
            except DeclarationParseError as exc:
                return exc
            if value is None:
                return None
            return re.sub(r"(?<!\S)(?:limited|ltd\.?)\s*\Z", "ltd", value.lower()).strip()

        amount = None
        currency = None
        if "Value" in indexed:
            i, f = indexed["Value"]
            location = f"{path}.{i}.Value"
            if f.type != "Decimal":
                raise DeclarationParseError(location, f.type, "expected Decimal monetary field")
            if f.value is not None:
                if type(f.value) not in (str, int) or not re.fullmatch(
                    r"-?[0-9]+(?:\.[0-9]+)?", str(f.value)
                ):
                    raise DeclarationParseError(location + ".value", f.value, "unsupported amount")
                amount = Decimal(str(f.value))
            code = (f.type_info or {}).get("currencyCode")
            if code is not None and not isinstance(code, str):
                raise DeclarationParseError(
                    location + ".typeInfo.currencyCode", code, "expected a currency string"
                )
            currency = code
        funder = preferred_funder(
            ultimate_payer=funder_name("UltimatePayerName"),
            donor=funder_name("DonorName"),
            payer=funder_name("PayerName"),
            group_donor=funder_name("Name") if donor else None,
        )
        # Donor fields describe the donor, not a different ultimate payer or intermediary.
        named_donor = funder_name("DonorName") or (funder_name("Name") if donor else None)
        donor_applies = funder == named_donor
        donor_status = text("DonorStatus") if donor_applies else None
        return cls(
            funder_name=funder,
            amount=amount,
            currency=currency,
            payment_type=text("PaymentType"),
            funder_kind=donor_status,
            company_number=text("DonorCompanyIdentifier") if donor_status == "Company" else None,
        )


class FieldGroup(Model):
    fields: list[SourceField]

    def parent_payer_applies(self, path: str) -> bool:
        for i, field in enumerate(self.fields):
            if field.name == "IsUltimatePayerDifferent":
                if field.value is not None and type(field.value) is not bool:
                    raise DeclarationParseError(
                        f"{path}.{i}.IsUltimatePayerDifferent.value",
                        field.value,
                        "expected a boolean",
                    )
                # A withheld different payer must not be attributed to the intermediary.
                return field.value is not True
        return True

    def funding(self, path: str) -> tuple[FundingEntry, ...]:
        entries: list[FundingEntry] = []
        for i, field in enumerate(self.fields):
            field.check_funding_shape(f"{path}.{i}.{field.name}")
        if any(f.name in {"Value", "PaymentType"} for f in self.fields):
            entries.append(FundingEntry.from_fields(self.fields, path))
        for i, field in enumerate(self.fields):
            if field.name == "Donors":
                if field.values is None:
                    raise DeclarationParseError(
                        f"{path}.{i}.Donors.values", None, "expected donor groups"
                    )
                for j, fields in enumerate(field.values):
                    entries.append(
                        FundingEntry.from_fields(
                            fields, f"{path}.{i}.Donors.values.{j}", donor=True
                        )
                    )
        return tuple(entries)


class SourceDeclaration(Model):
    id: PositiveID
    category: Category
    registrant: Registrant
    parent_id: PositiveID | None = Field(default=None, validation_alias="parentInterestId")
    versions: list[dict[str, JsonValue]] = Field(min_length=1)

    def latest_version_index(self) -> int:
        return latest_version(
            tuple(
                PublishedVersion(
                    published_on=VersionHeader.model_validate(v).source_register.published_date,
                    content={k: value for k, value in v.items() if k not in {"register", "links"}},
                )
                for v in self.versions
            )
        )

    def registration_date(self) -> date | None:
        """Read date metadata without interpreting funding or resolving parents."""
        return RegistrationDate.model_validate(
            self.versions[self.latest_version_index()]
        ).registration_date

    def latest_fields(self) -> tuple[FieldGroup, str]:
        first = self.latest_version_index()
        return FieldGroup.model_validate(self.versions[first]), f"versions.{first}.fields"

    def to_draft(self) -> DeclarationDraft:
        fields, path = self.latest_fields()
        funding = fields.funding(path)
        return DeclarationDraft(
            id=self.id,
            member_source_id=self.registrant.member.id,
            category_id=self.category.id,
            category_name=self.category.name,
            registration_date=self.registration_date(),
            funding=tuple(
                DomainFundingEntry.model_validate(entry.model_dump()) for entry in funding
            ),
            payer=FundingEntry.from_fields(fields.fields, path).funder_name,
            parent_id=self.parent_id,
            ultimate_payer_differs=self.parent_id is not None
            and not fields.parent_payer_applies(path),
        )


class Declaration(Model):
    """Legacy response-shaped view; acceptance rules live in the core draft."""

    id: PositiveID
    category: Category
    registrant: Registrant
    funding: tuple[FundingEntry, ...]
    payer: str | None
    registration_date: date | None = None

    def to_declaration(self) -> DomainDeclaration:
        return DomainDeclaration(
            id=self.id,
            member_source_id=self.registrant.member.id,
            category_id=self.category.id,
            category_name=self.category.name,
            registration_date=self.registration_date,
            funding=tuple(
                DomainFundingEntry.model_validate(entry.model_dump()) for entry in self.funding
            ),
            payer=self.payer,
        )

    @classmethod
    def from_source(cls, source: SourceDeclaration, *, parent: Self | None = None) -> Self:
        accepted = source.to_draft().accept(parent=parent.to_declaration() if parent else None)
        return cls(
            id=accepted.id,
            category=source.category,
            registrant=source.registrant,
            funding=tuple(
                FundingEntry.model_validate(entry.model_dump()) for entry in accepted.funding
            ),
            payer=accepted.payer,
            registration_date=accepted.registration_date,
        )

