class FieldGroup(Model):
    fields: list[SourceField]

    def parent_payer_applies(self, path: str) -> bool:
        for i, field in enumerate(self.fields):
            if field.name == "IsUltimatePayerDifferent":
                if field.value is not None and type(field.value) is not bool:
                    raise DeclarationParseError(
                        f"{path}.{i}.IsUltimatePayerDifferent.value",
                        field.value,
                        "expected a boolean",
                    )
                # A withheld different payer must not be attributed to the intermediary.
                return field.value is not True
        return True

    def funding(self, path: str) -> tuple[FundingEntry, ...]:
        entries: list[FundingEntry] = []
        for i, field in enumerate(self.fields):
            field.check_funding_shape(f"{path}.{i}.{field.name}")
        if any(f.name in {"Value", "PaymentType"} for f in self.fields):
            entries.append(FundingEntry.from_fields(self.fields, path))
        for i, field in enumerate(self.fields):
            if field.name == "Donors":
                if field.values is None:
                    raise DeclarationParseError(
                        f"{path}.{i}.Donors.values", None, "expected donor groups"
                    )
                for j, fields in enumerate(field.values):
                    entries.append(
                        FundingEntry.from_fields(
                            fields, f"{path}.{i}.Donors.values.{j}", donor=True
                        )
                    )
        return tuple(entries)


class SourceDeclaration(Model):
    id: PositiveID
    category: Category
    registrant: Registrant
    parent_id: PositiveID | None = Field(default=None, validation_alias="parentInterestId")
    versions: list[dict[str, JsonValue]] = Field(min_length=1)

    def latest_version_index(self) -> int:
        return latest_version(
            tuple(
                PublishedVersion(
                    published_on=VersionHeader.model_validate(v).source_register.published_date,
                    content={k: value for k, value in v.items() if k not in {"register", "links"}},
                )
                for v in self.versions
            )
        )

    def registration_date(self) -> date | None:
        """Read date metadata without interpreting funding or resolving parents."""
        return RegistrationDate.model_validate(
            self.versions[self.latest_version_index()]
        ).registration_date

    def latest_fields(self) -> tuple[FieldGroup, str]:
        first = self.latest_version_index()
        return FieldGroup.model_validate(self.versions[first]), f"versions.{first}.fields"

    def to_draft(self) -> DeclarationDraft:
        fields, path = self.latest_fields()
        funding = fields.funding(path)
        return DeclarationDraft(
            id=self.id,
            member_source_id=self.registrant.member.id,
            category_id=self.category.id,
            category_name=self.category.name,
            registration_date=self.registration_date(),
            funding=tuple(
                DomainFundingEntry.model_validate(entry.model_dump()) for entry in funding
            ),
            payer=FundingEntry.from_fields(fields.fields, path).funder_name,
            parent_id=self.parent_id,
            ultimate_payer_differs=self.parent_id is not None
            and not fields.parent_payer_applies(path),
        )


class Declaration(Model):
    """Legacy response-shaped view; acceptance rules live in the core draft."""

    id: PositiveID
    category: Category
    registrant: Registrant
    funding: tuple[FundingEntry, ...]
    payer: str | None
    registration_date: date | None = None

    def to_declaration(self) -> DomainDeclaration:
        return DomainDeclaration(
            id=self.id,
            member_source_id=self.registrant.member.id,
            category_id=self.category.id,
            category_name=self.category.name,
            registration_date=self.registration_date,
            funding=tuple(
                DomainFundingEntry.model_validate(entry.model_dump()) for entry in self.funding
            ),
            payer=self.payer,
        )

    @classmethod
    def from_source(cls, source: SourceDeclaration, *, parent: Self | None = None) -> Self:
        accepted = source.to_draft().accept(parent=parent.to_declaration() if parent else None)
        return cls(
            id=accepted.id,
            category=source.category,
            registrant=source.registrant,
            funding=tuple(
                FundingEntry.model_validate(entry.model_dump()) for entry in accepted.funding
            ),
            payer=accepted.payer,
            registration_date=accepted.registration_date,
        )
